import React, { useState, useEffect } from 'react';
import axios from 'axios';
import TeacherQuiz from './TeacherQuiz';
import ViewReports from './TeacherReports';

const axiosInstance = axios;

// --- 1. CONTENT MANAGER COMPONENT (Form + Rich Archive with Thumbnails) ---
function TeacherContent({ userName, teachingSubject, materials, fetchData, timetable, preSelectedGrade, setPreSelectedGrade }) {
  const [formTitle, setFormTitle] = useState('');
  const [formType, setFormType] = useState('PDF'); // PDF, Video, Past Paper
  const [formFilePath, setFormFilePath] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);

  const teacherGrades = Array.isArray(timetable) ? [...new Set(timetable.map(c => c.grade))] : [];
  const [formGrade, setFormGrade] = useState(teacherGrades[0] || 'Grade 9');

  useEffect(() => {
    if (preSelectedGrade) {
      setFormGrade(preSelectedGrade);
      setPreSelectedGrade(null);
    } else if (teacherGrades.length > 0 && !formGrade) {
      setFormGrade(teacherGrades[0]);
    }
  }, [preSelectedGrade, teacherGrades, formGrade, setPreSelectedGrade]);

  // 🧠 YouTube URL එකෙන් Thumbnail එක ඇදගැනීම සඳහා Video ID එක වෙන් කරගන්නා ලොජික් එක
  const getYoutubeId = (url) => {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('title', formTitle);
    formData.append('material_type', formType);
    formData.append('grade', formGrade);
    formData.append('subject', teachingSubject);
    formData.append('teacher_name', userName);

    // PDF හෝ Past Paper නම් ෆයිල් එක අප්ලෝඩ් කරයි, වීඩියෝ නම් ලින්ක් එක දමයි
    if ((formType === 'PDF' || formType === 'Past Paper') && selectedFile) {
        formData.append('file', selectedFile); 
    } else {
        formData.append('file_path', formFilePath);
    }

    axiosInstance.post('http://localhost:8082/api/add-material', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
    }).then(res => {
      if (res.data.status === "Success") {
        alert(`✅ ${formType} Published Successfully!`);
        fetchData(); 
        setFormTitle(''); 
        setFormFilePath(''); 
        setSelectedFile(null);
      }
    }).catch(err => console.log(err));
  };

  const handleDeleteMaterial = (id) => {
    if (window.confirm("Are you sure you want to permanently delete this item?")) {
      axiosInstance.delete(`http://localhost:8082/api/delete-material/${id}`)
        .then(res => {
          if (res.data.status === "Success") {
            alert("🗑️ Material removed from system matrix!");
            fetchData();
          }
        }).catch(err => console.log(err));
    }
  };

  const myMaterials = materials.filter(m => m.subject === teachingSubject);

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '30px' }}>
      
      {/* Upload Portal Form */}
      <div>
        <h2>📤 Content Manager Gateway ({teachingSubject})</h2>
        <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
          <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <input type="text" placeholder="Material Title (e.g., 2025 O/L Mathematics Past Paper)" value={formTitle} onChange={e => setFormTitle(e.target.value)} required style={styles.fullInput} />
            
            <div style={{ display: 'flex', gap: '20px' }}>
              <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={styles.fullInput}>
                {teacherGrades.length > 0 ? (
                  teacherGrades.map(g => <option key={g} value={g}>{g}</option>)
                ) : (
                  ['Grade 6', 'Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11', 'Grade 12'].map(g => <option key={g} value={g}>{g}</option>)
                )}
              </select>

              {/* 🟢 FIXED: Past Paper එකතු කරන ලද නව Dropdown එක */}
              <select value={formType} onChange={e => { setFormType(e.target.value); setSelectedFile(null); setFormFilePath(''); }} style={styles.fullInput}>
                <option value="PDF">📚 PDF Handout Documents</option>
                <option value="Past Paper">🎯 Official Past Papers</option>
                <option value="Video">🎬 Video Lesson URL</option>
              </select>
            </div>

            {formType === 'PDF' || formType === 'Past Paper' ? (
              <input type="file" accept=".pdf" onChange={e => setSelectedFile(e.target.files[0])} required style={styles.fullInput} />
            ) : (
              <input type="text" placeholder="YouTube Video URL (e.g., https://www.youtube.com/watch?v=...)" value={formFilePath} onChange={e => setFormFilePath(e.target.value)} required style={styles.fullInput} />
            )}
            
            <button type="submit" style={styles.publishBtn}>🚀 Publish Structure Archive</button>
          </form>
        </div>
      </div>

      {/* 🟢 RICH ARCHIVE TABLE WITH THUMBNAILS */}
      <div>
        <h3 style={{ margin: '0 0 12px 0', color: '#1e293b' }}>📂 Published Learning Materials & Past Papers Matrix</h3>
        <div style={{ backgroundColor: 'white', padding: '20px 25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b', fontSize: '13px', height: '40px' }}>
                <th>No.</th>
                <th>Thumbnail Preview</th>
                <th>Material Title</th>
                <th>Grade</th>
                <th>Classification Type</th>
                <th>Gateway Access Link</th>
                <th style={{ textAlign: 'center' }}>Management</th>
              </tr>
            </thead>
            <tbody>
              {myMaterials.length > 0 ? (
                myMaterials.map((m, index) => {
                  const ytId = getYoutubeId(m.file_path);
                  return (
                    <tr key={m.id || index} style={{ borderBottom: '1px solid #f8fafc', height: '75px', fontSize: '14px' }}>
                      <td style={{ fontWeight: 'bold', color: '#64748b' }}>{index + 1}</td>
                      
                      {/* 🟢 THUMBNAIL INJECTION COLUMN (පිස්සු හැදෙන තම්බ්නේල් කොටස) */}
                      <td style={{ padding: '8px 0' }}>
                        <div style={{ width: '90px', height: '55px', borderRadius: '8px', overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.06)', backgroundColor: '#f8fafc', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                          {m.material_type === 'Video' && ytId ? (
                            <img src={`https://img.youtube.com/vi/${ytId}/mqdefault.jpg`} alt="YT Cover" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                          ) : m.material_type === 'Past Paper' ? (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#fee2e2', color: '#b91c1c', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' }}>
                              <span style={{ fontSize: '14px' }}>📝</span>EXAM
                            </div>
                          ) : (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#e0f2fe', color: '#0369a1', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' }}>
                              <span style={{ fontSize: '14px' }}>📄</span>PDF
                            </div>
                          )}
                        </div>
                      </td>

                      <td style={{ fontWeight: '600', color: '#1e293b' }}>{m.title}</td>
                      <td><span style={{ backgroundColor: '#f1f5f9', padding: '3px 8px', borderRadius: '6px', fontSize: '12px', fontWeight: '500' }}>{m.grade}</span></td>
                      
                      <td>
                        <span style={{ 
                          padding: '4px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold',
                          backgroundColor: m.material_type === 'PDF' ? '#dcfce7' : m.material_type === 'Past Paper' ? '#fee2e2' : '#fff7ed', 
                          color: m.material_type === 'PDF' ? '#15803d' : m.material_type === 'Past Paper' ? '#b91c1c' : '#c2410c' 
                        }}>
                          {m.material_type}
                        </span>
                      </td>

                      <td>
                        {m.material_type === 'Video' ? (
                          <a href={m.file_path} target="_blank" rel="noreferrer" style={{ color: '#ea580c', fontWeight: 'bold', textDecoration: 'underline' }}>🎬 Streaming Link</a>
                        ) : (
                          <a href={`http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={{ color: '#0284c7', fontWeight: 'bold', textDecoration: 'underline' }}>📥 Open Document</a>
                        )}
                      </td>

                      <td style={{ textAlign: 'center' }}>
                        <button onClick={() => handleDeleteMaterial(m.id)} style={{ backgroundColor: '#fee2e2', color: '#b91c1c', border: 'none', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' }}>
                          🗑️ Delete
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
                    📭 No operational files or past papers hosted under this structure yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}

// --- 2. MAIN PORTAL WITH VALIDATIONS & REPORT VIEWS ---
export default function TeacherDashboard({ userName, userUsername, subject, qualifications, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [isEditing, setIsEditing] = useState(false);
  const [preSelectedGrade, setPreSelectedGrade] = useState(null);

  const fullSubject = subject || 'IT'; 
  const subjectParts = fullSubject.split(' - ');
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const uniqueAssignedGrades = Array.isArray(timetable) && timetable.length > 0
    ? [...new Set(timetable.map(c => c.grade))].join(', ')
    : 'Not Assigned Yet';

  const [profileData, setProfileData] = useState({ 
    name: userName, 
    username: userUsername, 
    qualifications, 
    email, 
    phone, 
    address,
    password: '' 
  });

  const fetchData = () => {
    axiosInstance.get('http://localhost:8082/api/learning-materials').then(res => setMaterials(Array.isArray(res.data) ? res.data : []));
    axiosInstance.get('http://localhost:8082/api/timetable').then(res => setTimetable(Array.isArray(res.data) ? res.data.filter(c => c.teacher === userName) : []));
  };

  useEffect(() => { fetchData(); }, [userName]);

  const handleProfileUpdate = () => {
    const cleanPhone = profileData.phone.replace(/[\s\-]/g, '');
    const phoneRegex = /^07[01245678][0-9]{7}$/;
    
    if (!phoneRegex.test(cleanPhone)) {
        alert("❌ Error: Invalid Sri Lankan mobile number!");
        return;
    }

    if (!profileData.username.trim()) {
        alert("❌ Error: Username cannot be empty!");
        return;
    }

    axiosInstance.post('http://localhost:8082/api/update-teacher-credentials', {
        currentUsername: userUsername,
        newUsername: profileData.username,
        newPassword: profileData.password || 'Teacher@123'
    }).then(res => {
        if (res.data.status === "Success") {
            alert("✅ Credentials updated successfully! Logging out...");
            handleLogout(); 
        }
    }).catch(err => console.log(err));

    setIsEditing(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <h1>Welcome back, {profileData.name}! 👋</h1>
              <p>System operational for target assigned structures: <strong>{uniqueAssignedGrades} ({teachingSubject})</strong></p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" textColor="#3b82f6" />
              <DashboardCard title="Assigned Grades" count={uniqueAssignedGrades} icon="🏫" textColor="#7c3aed" />
              <DashboardCard title="Total Resources" count={materials.filter(m => m.subject === teachingSubject).length} icon="📂" textColor="#eab308" />
            </div>
            
            <h3>🏫 Active Scheduled Timetable Mapping</h3>
            <p style={{ color: '#64748b', fontSize: '13px', marginTop: '-5px', marginBottom: '15px' }}>💡 Quick Action: Click any class card below to instantly manage its handouts and papers.</p>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
                {timetable.map(c => (
                  <div 
                    key={c.id} 
                    onClick={() => {
                      setPreSelectedGrade(c.grade);
                      setActiveTab('upload');
                    }}
                    style={{ 
                      backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderTop: '5px solid #15803d', cursor: 'pointer',
                      boxShadow: '0 4px 15px rgba(0,0,0,0.02)', transition: 'all 0.2s ease-in-out'
                    }}
                    onMouseOver={(e) => {
                      e.currentTarget.style.transform = 'translateY(-4px)';
                      e.currentTarget.style.boxShadow = '0 8px 20px rgba(0,0,0,0.06)';
                    }}
                    onMouseOut={(e) => {
                      e.currentTarget.style.transform = 'translateY(0)';
                      e.currentTarget.style.boxShadow = '0 4px 15px rgba(0,0,0,0.02)';
                    }}
                  >
                    <div style={{ fontWeight: 'bold', color: '#1e293b' }}>{c.grade} - {c.subject}</div>
                    <div style={{ fontSize: '13px', color: '#64748b', marginTop: '6px' }}>🕒 {c.day} ({c.time_slot})</div>
                  </div>
                ))}
            </div>
          </div>
        );

      case 'upload': 
        return <TeacherContent userName={userName} teachingSubject={teachingSubject} materials={materials} fetchData={fetchData} timetable={timetable} preSelectedGrade={preSelectedGrade} setPreSelectedGrade={setPreSelectedGrade} />;
      
      case 'quiz': 
        return <TeacherQuiz userName={userName} subject={fullSubject} qualifications={qualifications} />;
      
      case 'activities':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>🧩 Manage Interactive Learning Exercises</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <p style={{ color: '#64748b', marginBottom: '20px' }}>Create alternative interactive games for students to practice terms after lessons.</p>
              <div style={{ display: 'flex', gap: '25px' }}>
                <div style={{ flex: 1, padding: '20px', border: '1px dashed #cbd5e1', borderRadius: '10px', textAlign: 'center' }}>
                  <h3>🧩 Word Matching Grid</h3>
                  <button onClick={() => alert("Setting up Vocabulary Grid...")} style={styles.submitBtn}>Configure Game</button>
                </div>
                <div style={{ flex: 1, padding: '20px', border: '1px dashed #cbd5e1', borderRadius: '10px', textAlign: 'center' }}>
                  <h3>💡 True / False Flashcards</h3>
                  <button onClick={() => alert("Setting up Revision Flashcards...")} style={styles.submitBtn}>Configure Deck</button>
                </div>
              </div>
            </div>
          </div>
        );

      case 'reports':
        return <ViewReports subject={fullSubject} />;

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>👤 My Profile Settings & Validation Auditing</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', maxWidth: '500px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
                  <h3>Profile Records</h3>
                  {!isEditing ? <button onClick={() => setIsEditing(true)} style={styles.editProfileBtn}>✏️ Edit Profile</button> : <button onClick={handleProfileUpdate} style={styles.saveProfileBtn}>💾 Save Changes</button>}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                  <div><label style={styles.label}>Full Name</label><input type="text" value={profileData.name} onChange={e => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>LMS Username *</label><input type="text" value={profileData.username} onChange={e => setProfileData({...profileData, username: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>New Security Password *</label><input type="password" placeholder="Type new password to change..." value={profileData.password} onChange={e => setProfileData({...profileData, password: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>Audited Email Address</label><input type="text" value={profileData.email} onChange={e => setProfileData({...profileData, email: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>Validated Phone Number</label><input type="text" value={profileData.phone} onChange={e => setProfileData({...profileData, phone: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>TEACHER DASHBOARD</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard Overview" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'quiz'} onClick={() => setActiveTab('quiz')} icon="📝" text="Quiz & Exam Manager" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🧩" text="Manage Activities" />
          <SidebarBtn active={activeTab === 'reports'} onClick={() => setActiveTab('reports')} icon="📈" text="View Reports" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile Settings" />
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}><button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button></div>
      </div>
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>{renderContent()}</div>
    </div>
  );
}

const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${textColor}`, boxShadow: '0 4px 15px rgba(0,0,0,0.02)' }}>
    <div><p style={{ margin: 0, color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2 style={{ fontSize: '18px', whiteSpace: 'normal', wordBreak: 'break-word', marginTop: '5px' }}>{count}</h2></div>
    <div style={{ fontSize: '28px' }}>{icon}</div>
  </div>
);

const styles = {
  label: { display: 'block', marginBottom: '6px', color: '#475569', fontSize: '13px', fontWeight: 'bold' },
  inlineInput: { flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' },
  submitBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px' },
  fullInput: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '14px' },
  publishBtn: { padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', width: '100%', marginTop: '10px' },
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' },
  editProfileBtn: { padding: '6px 14px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  saveProfileBtn: { padding: '6px 14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  inputStyleProfile: (isEditing) => ({ width: '100%', padding: '12px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b', fontSize: '14px' })
};
